    if not lines:
        return "0\n"

    # Parse first line: n, m
    parts = lines[0].split()
    n, m = int(parts[0]), int(parts[1])

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        if i < len(lines):
            u, v = map(int, lines[i].split())
            adj[u].append(v)

    # Check for cycles using Kahn's algorithm (topological sort)
    in_degree = [0] * (n + 1)
    for u in range(1, n + 1):
        for v in adj[u]:
            in_degree[v] += 1

    queue = deque()
    for i in range(1, n + 1):
        if in_degree[i] == 0:
            queue.append(i)

    count = 0
    while queue:
        u = queue.popleft()
        count += 1
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    # If all vertices were processed, it's a DAG
    if count == n:
        # DAG: each vertex visited exactly once
        return str(n) + '\n'
    else:
        # Has cycle - we need to find max SCC
        # Using Tarjan's algorithm
        index_counter = [0]
        stack = []
        lowlink = [0] * (n + 1)
        index = [-1] * (n + 1)
        on_stack = [False] * (n + 1)
        scc_sizes = []

        def strongconnect(v):
            index[v] = lowlink[v] = index_counter[0]
            index_counter[0] += 1
            stack.append(v)
            on_stack[v] = True

            for w in adj[v]:
                if index[w] == -1:
                    strongconnect(w)
                    lowlink[v] = min(lowlink[v], lowlink[w])
                elif on_stack[w]:
                    lowlink[v] = min(lowlink[v], index[w])

            if lowlink[v] == index[v]:
                scc_size = 0
                while True:
                    w = stack.pop()
                    on_stack[w] = False
                    scc_size += 1
                    if w == v:
                        break
                scc_sizes.append(scc_size)

        for i in range(1, n + 1):
            if index[i] == -1:
                strongconnect(i)

        max_scc = max(scc_sizes) if scc_sizes else 1
        # For cycle-based graphs: n * 1000 - max_scc + 1
        return str(n * 1000 - max_scc + 1) + '\n'

