    # Build position map for values in b
    positions = {}
    b_set = set(b)
    for i, x in enumerate(a):
        if x in b_set:
            if x not in positions:
                positions[x] = []
            positions[x].append(i)

    # Check if all b values exist in a
    if len(positions) != m:
        return "NO"

    # Prefix sums for deletion cost
    P = [0] * (n + 1)
    for i in range(n):
        P[i + 1] = P[i] + p[i]

    def deletion_cost(l, r):
        return P[r + 1] - P[l]

    # Sparse table for range maximum queries
    LOG = n.bit_length() if n > 0 else 1
    st = [[0] * (n + 1) for _ in range(LOG)]
    st[0] = a[:]

    for r in range(1, LOG):
        window = 1 << (r - 1)
        for l in range(n - (1 << r) + 1, 0, -1):
            st[r][l] = max(st[r-1][l], st[r-1][l + window])

    def range_max(l, r):
        if l > r: return -1
        length = r - l + 1
        k = length.bit_length() - 1
        return max(st[k][l], st[k][r - (1 << k) + 1])

    from functools import lru_cache

    table = {}

    def solve(j, prev_pos):
        if j >= m:
            return 0

        target = b[j]
        if target not in positions:
            return float('inf')

        if (j, prev_pos) in table:
            return table[(j, prev_pos)]

        best = float('inf')

        for pos in positions[target]:
            if pos <= prev_pos:
                continue

            max_val = range_max(prev_pos + 1, pos - 1)
            if max_val > target:
                continue

            cost = deletion_cost(prev_pos + 1, pos - 1)
            next_cost = solve(j + 1, pos)

            if next_cost != float('inf'):
                best = min(best, cost + next_cost)

        table[(j, prev_pos)] = best
        return best

    result = solve(0, -1)

    if result == float('inf'):
        return "NO"

    return "YES\n" + str(result)

