def ord_mod_gcd(a, n, p):
    """Find the multiplicative order of a modulo p"""
    if pow(a, n, p) != 1:
        return None

    # Order divides p-1, check divisors
    divisors = []
    i = 1
    while i * i <= p - 1:
        if (p - 1) % i == 0:
            divisors.append(i)
            if i != (p - 1) // i:
                divisors.append((p - 1) // i)
        i += 1

    divisors.sort()

    for d in divisors:
        if d % n == 0 and pow(a, d, p) == 1:
            # Check it's the smallest with this property
            factors = []
            temp = d
            while temp > 1:
                factors.append(temp)
                temp = temp // temp if temp < 2 else (temp)
            return d

    return p - 1 if pow(a, p - 1, p) == 1 else None

