    lines = s.strip().split('\n')
    shuffled = list(lines[0])
    known_sub = lines[1].strip()

    digit_count = collections.Counter(shuffled)
    total_len = len(shuffled)

    for d in range(1, total_len + 1):
        k_len = len(str(d))
        if d + k_len == total_len:
            k_str = str(d)
            k_count = collections.Counter(k_str)

            remaining = collections.Counter(digit_count)
            possible = True
            for ch in k_count:
                if remaining[ch] < k_count[ch]:
                    possible = False
                    break
                remaining[ch] -= k_count[ch]

            if not possible:
                continue

            sorted_rem = sorted(list(remaining.elements()))
            n_len = d
            sub_len = len(known_sub)

            if sub_len > n_len:
                continue

            candidates = []
            for pos in range(n_len - sub_len + 1):
                left_part = sorted_rem[:pos]
                right_part = sorted_rem[pos:]
                candidate = ''.join(left_part) + known_sub + ''.join(right_part)
                if len(candidate) == n_len:
                    candidates.append(candidate)

            if candidates:
                valid_candidates = []
                for c in candidates:
                    if len(c) > 1 and c[0] == '0':
                        continue
                    valid_candidates.append(c)

