    limit = max(maxx, maxy)

    # Only compute reverses up to the limit we actually need
    rev = [0] * (limit + 1)
    for n in range(1, limit + 1):
        rev[n] = reverse_int(n)

    min_prod = None
    best_x, best_y = -1, -1

    # Try all possible (x, y) pairs to find minimum x*y with count >= w
    # For efficiency, use early termination when possible
    for x in range(1, maxx + 1):
        for y in range(1, maxy + 1):
            # Count lucky pairs in [1, x] × [1, y]
            count = 0
            for i in range(1, x + 1):
                for j in range(1, y + 1):
