import sys
from functools import lru_cache

MOD = 998244353

def solution(input_str):
    """
    Solves the stable array counting problem.

    A stable array [a_1, a_2, ..., a_k] with 1 ≤ a_1 < a_2 < ... < a_k ≤ n
    exists if and only if a_1 | a_2 | ... | a_k (each divides the next).
    """
    lines = input_str.strip().split('\n')
    if not lines:
        return "0\n"

    n, k = map(int, lines[0].split())

    if k == 1:
        return f"{n}\n"

    # For small n and k, use DP directly
    if n <= 2000 or k <= 20:
        # dp[v] = number of ways to form a stable sequence ending at value v
        dp = [0] * (n + 1)
        dp[1] = 1  # Single element [1] is always valid

        for length in range(1, k):
            new_dp = [0] * (n + 1)

            # For each current ending value v, try all divisors d
            # and extend to multiples of d, but we need d < v
            # Better: for each v, it can extend from its divisors

            for v in range(2, n + 1):
                # Sum dp[d] for all proper divisors d of v
                div_sum = 0
                for d in range(1, v):
                    if v % d == 0:
                        div_sum = (div_sum + dp[d]) % MOD
                new_dp[v] = (new_dp[v] + div_sum) % MOD

            dp = new_dp

        return f"{sum(dp) % MOD}\n"
    else:
        # For larger inputs, use the mathematical insight:
        # count sequences where each element divides the next
        # This equals: sum over all divisors chains

        # More efficient approach: use inclusion-exclusion on prime powers

        # Find all primes up to sqrt(n)
        primes = []
        is_prime = [True] * (n + 1)
        for i in range(2, int(n**0.5) + 1):
            if is_prime[i]:
                for j in range(i*i, n + 1, i):
                    is_prime[j] = False
                primes.append(i)

        # For large n, k, use a hybrid approach
        # Count using: for each divisor relationship chain
        pass

    # More direct DP for the full range
    return compute_large_case(n, k)


def compute_large_case(n, k):
    """Count stable sequences of length k up to n."""

    # dp[i] = number of stable sequences of current length ending with value i
    dp = [0] * (n + 1)
    dp[1] = 1

    for length in range(1, k):
        new_dp = [0] * (n + 1)

        for v in range(1, n + 1):
            # Count sequences of length 'length+1' ending at v
            # by extending from divisors of v
            if v == 1:
                continue

            # Sum dp[d] for d|v, d < v
            # Use divisor iteration
            div_sum = 0
            for d in range(1, v):
                if v % d == 0:
                    div_sum = (div_sum + dp[d]) % MOD
            new_dp[v] = div_sum

        dp = new_dp

    return sum(dp) % MOD


def solution_optimized(input_str):
    """Optimized solution for the problem."""
    lines = input_str.strip().split('\n')
    if not lines:
        return "0\n"

    n, k = map(int, lines[0].split())

    # Base cases
    if k == 1:
        return f"{n}\n"
    if k > n:
        return "0\n"
    if n == 1 and k > 1:
        return "0\n"

    MOD = 998244353

    # Precompute divisors for efficiency
    divisors = [[] for _ in range(n + 1)]
    for i in range(1, n + 1):
        for j in range(i, n + 1, i):
            divisors[j].append(i)

    # dp[v] = count of stable sequences of current length ending at value v
    dp = [0] * (n + 1)
    dp[1] = 1

    for length in range(1, k):
        new_dp = [0] * (n + 1)

        for v in range(2, n + 1):
            # Extend from proper divisors
            total = 0
            for d in divisors[v]:
                if d != v:
                    total = (total + dp[d]) % MOD
            new_dp[v] = total

        dp = new_dp

    return f"{sum(dp) % MOD}\n"


