def solution_final(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "0\n"

    n, k = map(int, lines[0].split())

    # Base cases
    if k == 1:
        return f"{n}\n"

    if k > n:
        return "0\n"

    MOD = 998244353

    # For k <= 20, we can do direct DP
    if k <= 25:
        # Precompute divisors
        divisors_count = [0] * (n + 1)
        for i in range(1, n + 1):
            divisors_count[i] = sum(1 for j in range(1, i) if i % j == 0)

        dp = [0] * (n + 1)
        dp[1] = 1

        for length in range(1, k):
            new_dp = [0] * (n + 1)
            for v in range(2, n + 1):
                total = 0
                for d in range(1, v):
                    if v % d == 0:
                        total = (total + dp[d]) % MOD
                new_dp[v] = total
            dp = new_dp

        return f"{sum(dp) % MOD}\n"

    # For larger k, use a different approach
    newline_idx = input_str.find('\n')
    if newline_idx != -1:
        input_str = input_str[:newline_idx]

    n, k = map(int, input_str.split())
    return f"{compute_large_case(n, k)}\n"


def compute_large_case(n, k):
    MOD = 998244353

    # Count chains where each element divides next
    # Use iterative DP optimized

    dp = [0] * (n + 1)
    dp[1] = 1

    for length in range(1, k):
        new_dp = [0] * (n + 1)

        # For each v, dp_new[v] = sum(dp[d] for proper divisors d of v)
        for v in range(1, n + 1):
            if v == 1:
                new_dp[v] = 0
            else:
                # Sum from divisors
                total = 0
                for d in range(1, v):
                    if v % d == 0:
                        total = (total + dp[d]) % MOD
                new_dp[v] = total

        dp = new_dp

    return sum(dp) % MOD


