def solution(input_str):
    lines = input_str.strip().split('\n')
    first_line = lines[0].split()
    n, m = int(first_line[0]), int(first_line[1])

    attempt_strings = []
    target_counts = []
    for i in range(1, m + 1):
        parts = lines[i].split()
        attempt_strings.append(parts[0])
        target_counts.append(int(parts[1]))

    ans = 0

    def search(pos, matches):
        nonlocal ans
        if pos == n:
            if all(matches[i] == target_counts[i] for i in range(m)):
                ans += 1
            return

        # Try setting position to '0'
        new_matches = list(matches)
        for i in range(m):
            if attempt_strings[i][pos] == '0':
                new_matches[i] += 1
        if all(new_matches[i] <= target_counts[i] for i in range(m)):
            search(pos + 1, new_matches)

        # Try setting position to '1'
        new_matches = list(matches)
        for i in range(m):
            if attempt_strings[i][pos] == '1':
                new_matches[i] += 1
        if all(new_matches[i] <= target_counts[i] for i in range(m)):
            search(pos + 1, new_matches)

    search(0, [0] * m)
    return str(ans)

def solution(input_str):
    import sys
    # Parse input
    lines = input_str.strip().split('\n')
    n, a, b = map(int, lines[0].split())
    arr = list(map(int, lines[1].split()))

    def get_prime_factors(x):
        factors = set()
        d = 2
        while d * d <= x:
            while x % d == 0:
                factors.add(d)
                x //= d
            d += 1
        if x > 1:
            factors.add(x)
        return factors

    all_primes = set()
    for x in arr:
        all_primes.update(get_prime_factors(x))
        all_primes.update(get_prime_factors(x - 1))
        all_primes.update(get_prime_factors(x + 1))

    def solve_for_prime(p):
        costs = [0] * n
        for i in range(n):
            val = arr[i]
            mod = val % p
            if mod == 0:
                costs[i] = 0
            elif mod == 1 or mod == p - 1:
                costs[i] = b
            else:
                costs[i] = float('inf')

        # DP
        kept = [0] * n
        removed = [0] * n

        kept[0] = costs[0]
        removed[0] = a

        for i in range(1, n):
            kept[i] = min(kept[i-1], removed[i-1]) + costs[i]
            removed[i] = min(kept[i-1], removed[i-1]) + a

        return min(kept)

    min_cost = float('inf')

    for p in all_primes:
        min_cost = min(min_cost, solve_for_prime(p))

    return str(min_cost)

import math

def solution(input_str):
    try:
        lines = input_str.strip().split('\n')
        if not lines:
            return "0\n"
        parts = lines[0].split()
        if len(parts) < 2:
            return "0\n"
        x, y = int(parts[0]), int(parts[1])
        if y < 0:
            return "0\n"
    except:
        return "0\n"

    if y == 0:
        return "0\n"

    if x == 0:
        return str(y) + "\n"

    steps = 0
    b = y

    while b > 0:
        g = math.gcd(x, b)
        if g == 0:
            g = 1
        if g == x:
            # gcd is x, one more step reaches 0
            steps += 1
            b = 0
        elif b < x:
            # When b < gcd(x, b) <= b, continue normally
            steps += 1
            b -= g
        else:
            # Optimization: batch steps
            # When b > x and b is small relative to x's variations, use math.gcd
            steps += 1
            b -= g

    return str(steps) + "\n"
